import type { Person } from './person-model';
import type { Request } from './request-model';
import type { Workspace } from './workspace-model';

export const RequestReminderStatusKeyToLabel = {
  'Scheduled': 'Scheduled',
  'Sent': 'Sent',
  'Cancelled': 'Cancelled'
} as const;
export type RequestReminderStatusKey = keyof typeof RequestReminderStatusKeyToLabel;

export interface RequestReminder {
  /**
   * @displayName Request Reminder ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName ReminderName
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  reminderName: string;
  /**
   * @displayName CreatedAt
   * @validationRule Required for create/update operations
   */
  createdAt: string;
  /**
   * @displayName RemindAt
   * @validationRule Required for create/update operations
   */
  remindAt: string;
  /**
   * @displayName RemindPersonId
   * @validationRule Required for create/update operations
   */
  remindPersonId: Pick<Person, 'id' | 'displayName'>;
  /**
   * @displayName RequestId
   * @validationRule Required for create/update operations
   */
  requestId: Pick<Request, 'id' | 'requestNumber'>;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: RequestReminderStatusKey;
  /**
   * @displayName WorkspaceId
   * @validationRule Required for create/update operations
   */
  workspaceId: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _RequestReminder = 'RequestReminder' as const;